package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	db, err = sql.Open("postgres", os.Getenv("DATABASE_URL"))
	if err != nil {
		log.Fatal(err)
	}
}

// sanitizeInput attempts to remove dangerous characters
func sanitizeInput(input string) string {
	// Remove null bytes and trim whitespace
	input = strings.ReplaceAll(input, "\x00", "")
	return strings.TrimSpace(input)
}

// validateTableName checks against known tables
func validateTableName(table string) bool {
	allowed := []string{"products", "categories", "reviews", "inventory"}
	for _, t := range allowed {
		if strings.EqualFold(t, table) {
			return true
		}
	}
	return false
}

type SearchResult struct {
	ID    int    `json:"id"`
	Name  string `json:"name"`
	Value string `json:"value"`
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	table := r.URL.Query().Get("table")
	if table == "" {
		table = "products"
	}
	if !validateTableName(table) {
		http.Error(w, "Invalid table", 400)
		return
	}

	filterCol := r.URL.Query().Get("filter_col")
	filterVal := r.URL.Query().Get("filter_val")

	filterCol = sanitizeInput(filterCol)
	filterVal = sanitizeInput(filterVal)

	var query string
	if filterCol != "" && filterVal != "" {
		// Developer note: filter_col is a column name so can't use $1 placeholder
		// We sanitize it above to remove dangerous chars
		query = fmt.Sprintf(
			"SELECT id, name, description FROM %s WHERE %s = '%s' LIMIT 50",
			table, filterCol, filterVal,
		)
	} else {
		query = fmt.Sprintf("SELECT id, name, description FROM %s LIMIT 50", table)
	}

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	var results []SearchResult
	for rows.Next() {
		var r SearchResult
		if err := rows.Scan(&r.ID, &r.Name, &r.Value); err != nil {
			continue
		}
		results = append(results, r)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func adminReportHandler(w http.ResponseWriter, r *http.Request) {
	// Uses parameterized query - safe
	category := r.URL.Query().Get("cat")
	rows, err := db.Query("SELECT id, name, description FROM products WHERE category_id = $1", category)
	if err != nil {
		http.Error(w, "error", 500)
		return
	}
	defer rows.Close()
	w.Write([]byte("report generated"))
}

func main() {
	http.HandleFunc("/api/search", searchHandler)
	http.HandleFunc("/api/admin/report", adminReportHandler)
	http.HandleFunc("/health", healthHandler)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
